Sure thing—great to build on the previous examples! I'll provide practical, authentic code snippets tailored for your IoT curriculum. These are designed for real-world student projects (e.g., ESP32 with sensors like BME280 for temp/hum/press, TSL2561 for light via I2C). I've kept them modular, commented heavily for teaching, and used concrete values:

- **Magic bytes/sync**: `0xAA 0x55` (common framing pattern, easy hex decode).
- **Error detection**: CRC-16-CCITT (poly 0x1021, standard for embedded; init 0xFFFF).
- **Numeric concretes**: Device IDs 0x0101-0xFFFF, seq starts at 0x00, timestamps in seconds.

All code is tested mentally for ESP32 (adjust pins for RP2040/STM32). Use Serial Monitor or logic analyzer for verification.

### 1. Complex Multi-Sensor Packet Structure
**Byte Layout** (28 bytes total, compact for radio/UART):
```
Offset | Field          | Size | Type       | Example Value (hex)
  0-1  | Sync Pattern   | 2B   | Fixed      | AA 55
  2-3  | Device ID      | 2B   | uint16 BE  | 01 01  (e.g., sensor #1)
  4    | Packet Type    | 1B   | uint8      | 01 (data), 02 (config ack)
  5    | Sequence #     | 1B   | uint8      | 00-FF (rolls over)
  6-9  | Timestamp      | 4B   | uint32 BE  | e.g., 00 00 01 A4 (420s)
 10-11 | Temp           | 2B   | int16 BE   | e.g., 01 90 (40.0°C *10)
 12-13 | Humidity       | 2B   | uint16 BE  | e.g., 05 DC (1500 = 75.0%)
 14-17 | Pressure       | 4B   | uint32 BE  | e.g., 00 01 0B B8 (101320 Pa)
 18-21 | Light (Lux)    | 4B   | uint32 BE  | e.g., 00 00 27 10 (10000 lux)
 22-25 | CRC-16         | 2B   | uint16 BE  | Computed (see code)
```

**Calibration Constants** (arrays for linear calib: `value = (raw - offset) * scale`):
- Temp: `[0.5, 0.1]` (voltage offset 0.5V, 0.1°C/V)
- Hum: `[10.0, 0.8]`
- Press: `[90000.0, 100.0]` (Pa)
- Light: `[0.0, 1.2]`

#### MicroPython Pack Function
```python
import struct
import time
import uhashlib  # For CRC (or implement poly)

# CRC-16-CCITT poly
def crc16(data):
    crc = 0xFFFF
    for b in data:
        crc ^= b << 8
        for _ in range(8):
            crc = (crc << 1) ^ 0x1021 if crc & 0x8000 else crc << 1
            crc &= 0xFFFF
    return crc

CALIB = {
    'temp': [0.5, 0.1],
    'hum': [10.0, 0.8],
    'press': [90000.0, 100.0],
    'light': [0.0, 1.2]
}

def pack_sensor_packet(dev_id=0x0101, seq=0, temp=25.0, hum=60.0, press=101300, light=5000):
    ts = int(time.ticks_ms() / 1000)
    pkt = struct.pack('>HHBBIHHII',  # > = big-endian
                      0xAA55, dev_id, 0x01, seq, ts,
                      int(temp * 10), int(hum * 10),
                      int(press), int(light))
    crc = crc16(pkt)
    pkt += struct.pack('>H', crc)
    return pkt

# Example usage (integrate with sensors)
pkt = pack_sensor_packet(temp=40.5, hum=75.2)
print([hex(b) for b in pkt])  # Verify: ['0xaa', '0x55', '0x1', '0x1', ...]
uart.write(pkt)
```

#### C Pack Function (Arduino ESP32)
```c
#include <Arduino.h>

// CRC-16-CCITT
uint16_t crc16(const uint8_t* data, size_t len) {
  uint16_t crc = 0xFFFF;
  for (size_t i = 0; i < len; i++) {
    crc ^= (uint16_t)data[i] << 8;
    for (uint8_t j = 0; j < 8; j++) {
      crc = (crc & 0x8000) ? (crc << 1) ^ 0x1021 : crc << 1;
      crc &= 0xFFFF;
    }
  }
  return crc;
}

float calib_temp[2] = {0.5, 0.1};
float calib_hum[2] = {10.0, 0.8};
float calib_press[2] = {90000.0, 100.0};
float calib_light[2] = {0.0, 1.2};

uint8_t packet[28];

void pack_sensor_packet(uint16_t dev_id, uint8_t seq, float temp, float hum, uint32_t press, uint32_t light) {
  uint32_t ts = millis() / 1000;

  // Sync + header (bytes 0-9)
  packet[0] = 0xAA; packet[1] = 0x55;
  packet[2] = dev_id >> 8; packet[3] = dev_id & 0xFF;
  packet[4] = 0x01; packet[5] = seq;
  packet[6] = (ts >> 24) & 0xFF; packet[7] = (ts >> 16) & 0xFF;
  packet[8] = (ts >> 8) & 0xFF; packet[9] = ts & 0xFF;

  // Data (10-21)
  int16_t i_temp = (int16_t)(temp * 10);
  uint16_t u_hum = (uint16_t)(hum * 10);
  packet[10] = i_temp >> 8; packet[11] = i_temp & 0xFF;
  packet[12] = u_hum >> 8; packet[13] = u_hum & 0xFF;
  packet[14] = (press >> 24) & 0xFF; packet[15] = (press >> 16) & 0xFF;
  packet[16] = (press >> 8) & 0xFF; packet[17] = press & 0xFF;
  packet[18] = (light >> 24) & 0xFF; packet[19] = (light >> 16) & 0xFF;
  packet[20] = (light >> 8) & 0xFF; packet[21] = light & 0xFF;

  // CRC (22-25)
  uint16_t crc = crc16(packet, 22);
  packet[22] = crc >> 8; packet[23] = crc & 0xFF;
  packet[24] = 0x00; packet[25] = 0x00;  // Reserved/padding
}

// Usage
pack_sensor_packet(0x0101, 0, 40.5, 75.2, 101320, 10000);
Serial.write(packet, 28);
```

**Teaching Notes**: Students can unpack on gateway with `struct.unpack` (Py) or bit-shifting (C). Verify CRC before use. Integrate real sensors: BME280 lib for press/hum/temp.

### 2. Device Configuration Protocol (C for ESP32 Sensor)
Gateway → Sensor via UART. Commands are request-response. Sensor ACKs with same header + status.

**Command Codes**:
- `0x10`: SET_DEV_ID (params: new uint16 ID)
- `0x11`: SET_CALIB_TEMP (params: float offset (4B), float scale (4B) — use `union` for pack)
- `0x12`: SET_INTERVAL (params: uint16 ms)
- `0xFF`: GET_STATUS (response: current config)

Byte Layout (variable len): Sync(2) + DevID(2) + Cmd(1) + Len(1) + Params(Len bytes) + CRC(2)

```c
#define CMD_SET_ID 0x10
#define CMD_SET_CALIB_TEMP 0x11
#define CMD_SET_INTERVAL 0x12
#define CMD_GET_STATUS 0xFF
#define ACK_OK 0x00
#define ACK_NACK 0x01

uint16_t dev_id = 0x0101;
uint16_t interval_ms = 5000;
float calib_temp[2] = {0.5, 0.1};

uint8_t rx_buf[32];
uint8_t tx_buf[32];

void send_ack(uint8_t status, uint8_t cmd) {
  tx_buf[0] = 0xAA; tx_buf[1] = 0x55;
  tx_buf[2] = dev_id >> 8; tx_buf[3] = dev_id;
  tx_buf[4] = cmd; tx_buf[5] = 0x01;  // Len=1 (status)
  tx_buf[6] = status;
  uint16_t crc = crc16(tx_buf, 7);  // Reuse CRC from pkt1
  tx_buf[7] = crc >> 8; tx_buf[8] = crc & 0xFF;
  Serial.write(tx_buf, 9);
}

void handle_config() {
  if (Serial.available() >= 9) {  // Min cmd len
    Serial.readBytes(rx_buf, Serial.available());
    if (rx_buf[0] == 0xAA && rx_buf[1] == 0x55) {
      uint16_t rx_id = (rx_buf[2] << 8) | rx_buf[3];
      uint8_t cmd = rx_buf[4];
      uint8_t len = rx_buf[5];
      // CRC check (simplified; full impl compares)

      if (rx_id == dev_id || rx_id == 0xFFFF) {  // Broadcast OK
        switch (cmd) {
          case CMD_SET_ID:
            if (len == 2) {
              dev_id = (rx_buf[6] << 8) | rx_buf[7];
              send_ack(ACK_OK, cmd);
            }
            break;
          case CMD_SET_CALIB_TEMP:
            if (len == 8) {
