0-3: Nonce (uint32 rand)
4: Key ID (0x01 = shared AES128)
Payload: XOR-encrypted sensor packet (key=<GENERIC_CREDENTIAL_REDACTED> placeholder)
```

```python
import machine
import time
import random
import sx127x  # pip install sx127x or course lib

# LoRa setup (SF12, 125kHz BW for long-range ~10km)
lora = sx127x.SX127x(spi_bus=machine.SPI(1, baudrate=10000000, polarity=0, phase=0),
                     cs=machine.Pin(5, machine.Pin.OUT),
                     dio0=machine.Pin(2, machine.Pin.IN))
lora.begin()
lora.set_frequency(915000000)  # Adjust band
lora.set_spreading_factor(12)
lora.set_signal_bandwidth(125000)
lora.set_coding_rate(8)
lora.set_tx_power(20)

XOR_KEY = b'\xa1\xb2\xc3\xd4\xe5\xf6\x78\x90\x12\x34\x56\x78\x90\xab\xcd\xef'  # 16B AES-sized

def encrypt_payload(payload, key):
    return bytes(a ^ b for a, b in zip(payload, key * (len(payload) // 16 + 1)))

def pack_lora_packet(temp=25.0, hum=60.0, press=101300, light=5000, dev_id=0x0101, seq=0):
    sensor_pkt = pack_sensor_packet(dev_id, seq, temp, hum, press, light)  # From #1
    nonce = random.getrandbits(32)
    key_id = 0x01
    crypto_hdr = struct.pack('>IB', nonce, key_id)
    enc_payload = encrypt_payload(sensor_pkt, XOR_KEY)
    full_pkt = crypto_hdr + enc_payload
    return full_pkt  # CRC already in sensor_pkt

# TX loop
seq = 0
while True:
    pkt = pack_lora_packet(seq=seq)
    lora.write(full_pkt)  # SX127x send (blocks)
    print("LoRa TX:", [hex(b) for b in pkt[:10]])  # Debug hdr
    seq = (seq + 1) % 256
    time.sleep(30)  # Duty cycle
```

