  packet[6] = i_temp & 0xFF;
  packet[7] = (i_hum >> 8) & 0xFF;
  packet[8] = i_hum & 0xFF;

  // Checksum
  uint8_t chksum = 0;
  for (int i = 1; i < 9; i++) chksum += packet[i];
  packet[9] = chksum % 256;
}

void setup() {
