import struct
import time
import uhashlib  # For CRC (or implement poly)

# CRC-16-CCITT poly
def crc16(data):
    crc = 0xFFFF
    for b in data:
        crc ^= b << 8
        for _ in range(8):
            crc = (crc << 1) ^ 0x1021 if crc & 0x8000 else crc << 1
            crc &= 0xFFFF
    return crc

CALIB = {
    'temp': [0.5, 0.1],
    'hum': [10.0, 0.8],
    'press': [90000.0, 100.0],
    'light': [0.0, 1.2]
}

def pack_sensor_packet(dev_id=0x0101, seq=0, temp=25.0, hum=60.0, press=101300, light=5000):
    ts = int(time.ticks_ms() / 1000)
    pkt = struct.pack('>HHBBIHHII',  # > = big-endian
                      0xAA55, dev_id, 0x01, seq, ts,
                      int(temp * 10), int(hum * 10),
                      int(press), int(light))
    crc = crc16(pkt)
    pkt += struct.pack('>H', crc)
    return pkt

# Example usage (integrate with sensors)
