#### C Pack Function (Arduino ESP32)
```c
#include <Arduino.h>

// CRC-16-CCITT
uint16_t crc16(const uint8_t* data, size_t len) {
  uint16_t crc = 0xFFFF;
  for (size_t i = 0; i < len; i++) {
    crc ^= (uint16_t)data[i] << 8;
    for (uint8_t j = 0; j < 8; j++) {
      crc = (crc & 0x8000) ? (crc << 1) ^ 0x1021 : crc << 1;
      crc &= 0xFFFF;
    }
  }
  return crc;
}

float calib_temp[2] = {0.5, 0.1};
float calib_hum[2] = {10.0, 0.8};
float calib_press[2] = {90000.0, 100.0};
float calib_light[2] = {0.0, 1.2};

uint8_t packet[28];

void pack_sensor_packet(uint16_t dev_id, uint8_t seq, float temp, float hum, uint32_t press, uint32_t light) {
  uint32_t ts = millis() / 1000;

  // Sync + header (bytes 0-9)
  packet[0] = 0xAA; packet[1] = 0x55;
  packet[2] = dev_id >> 8; packet[3] = dev_id & 0xFF;
  packet[4] = 0x01; packet[5] = seq;
  packet[6] = (ts >> 24) & 0xFF; packet[7] = (ts >> 16) & 0xFF;
  packet[8] = (ts >> 8) & 0xFF; packet[9] = ts & 0xFF;

  // Data (10-21)
  int16_t i_temp = (int16_t)(temp * 10);
  uint16_t u_hum = (uint16_t)(hum * 10);
  packet[10] = i_temp >> 8; packet[11] = i_temp & 0xFF;
  packet[12] = u_hum >> 8; packet[13] = u_hum & 0xFF;
  packet[14] = (press >> 24) & 0xFF; packet[15] = (press >> 16) & 0xFF;
  packet[16] = (press >> 8) & 0xFF; packet[17] = press & 0xFF;
  packet[18] = (light >> 24) & 0xFF; packet[19] = (light >> 16) & 0xFF;
  packet[20] = (light >> 8) & 0xFF; packet[21] = light & 0xFF;

  // CRC (22-25)
  uint16_t crc = crc16(packet, 22);
  packet[22] = crc >> 8; packet[23] = crc & 0xFF;
  packet[24] = 0x00; packet[25] = 0x00;  // Reserved/padding
}

// Usage
pack_sensor_packet(0x0101, 0, 40.5, 75.2, 101320, 10000);
Serial.write(packet, 28);
```

**Teaching Notes**: Students can unpack on gateway with `struct.unpack` (Py) or bit-shifting (C). Verify CRC before use. Integrate real sensors: BME280 lib for press/hum/temp.

### 2. Device Configuration Protocol (C for ESP32 Sensor)
Gateway → Sensor via UART. Commands are request-response. Sensor ACKs with same header + status.

**Command Codes**:
- `0x10`: SET_DEV_ID (params: new uint16 ID)
- `0x11`: SET_CALIB_TEMP (params: float offset (4B), float scale (4B) — use `union` for pack)
- `0x12`: SET_INTERVAL (params: uint16 ms)
- `0xFF`: GET_STATUS (response: current config)

Byte Layout (variable len): Sync(2) + DevID(2) + Cmd(1) + Len(1) + Params(Len bytes) + CRC(2)

```c
#define CMD_SET_ID 0x10
#define CMD_SET_CALIB_TEMP 0x11
#define CMD_SET_INTERVAL 0x12
#define CMD_GET_STATUS 0xFF
#define ACK_OK 0x00
#define ACK_NACK 0x01

uint16_t dev_id = 0x0101;
uint16_t interval_ms = 5000;
float calib_temp[2] = {0.5, 0.1};

uint8_t rx_buf[32];
uint8_t tx_buf[32];

void send_ack(uint8_t status, uint8_t cmd) {
  tx_buf[0] = 0xAA; tx_buf[1] = 0x55;
  tx_buf[2] = dev_id >> 8; tx_buf[3] = dev_id;
  tx_buf[4] = cmd; tx_buf[5] = 0x01;  // Len=1 (status)
  tx_buf[6] = status;
  uint16_t crc = crc16(tx_buf, 7);  // Reuse CRC from pkt1
  tx_buf[7] = crc >> 8; tx_buf[8] = crc & 0xFF;
  Serial.write(tx_buf, 9);
}

void handle_config() {
  if (Serial.available() >= 9) {  // Min cmd len
    Serial.readBytes(rx_buf, Serial.available());
    if (rx_buf[0] == 0xAA && rx_buf[1] == 0x55) {
      uint16_t rx_id = (rx_buf[2] << 8) | rx_buf[3];
      uint8_t cmd = rx_buf[4];
      uint8_t len = rx_buf[5];
      // CRC check (simplified; full impl compares)

      if (rx_id == dev_id || rx_id == 0xFFFF) {  // Broadcast OK
        switch (cmd) {
          case CMD_SET_ID:
            if (len == 2) {
              dev_id = (rx_buf[6] << 8) | rx_buf[7];
              send_ack(ACK_OK, cmd);
            }
            break;
          case CMD_SET_CALIB_TEMP:
            if (len == 8) {
              memcpy(calib_temp, &rx_buf[6], 8);  // Floats
              send_ack(ACK_OK, cmd);
            }
            break;
          // Add others...
          case CMD_GET_STATUS:
            // Pack response with current values (exercise for students)
            send_ack(0x00, cmd);
            break;
        }
      }
    }
  }
}

void setup() { Serial.begin(115200); }
void loop() { handle_config(); delay(10); }
```

**Teaching Notes**: Gateway sends e.g., `[AA 55 FF FF 10 02 01 02 XX XX]` (set ID 0x0102). Students implement CRC check/full unpack. Secure with auth later.

### 3. MicroPython LoRa Communication (ESP32 + SX1278)
Assumes SX1276/78 HAT (SPI pins: SCK=18,MISO=19,MOSI=23,CS=5,DIO0=2). Use `micropython-sx127x` lib (install via upip or course GitHub). Packet uses above structure + crypto header: Nonce(4B) + KeyID(1B) + Encrypted Payload (note: simple XOR key for edu; real: AES via `ucryptolib`).

**Crypto Header** (prepended to sensor packet):
```
0-3: Nonce (uint32 rand)
4: Key ID (0x01 = shared AES128)
Payload: XOR-encrypted sensor packet (key=<GENERIC_CREDENTIAL_REDACTED> placeholder)
```

```python
import machine
import time
import random
import sx127x  # pip install sx127x or course lib

# LoRa setup (SF12, 125kHz BW for long-range ~10km)
lora = sx127x.SX127x(spi_bus=machine.SPI(1, baudrate=10000000, polarity=0, phase=0),
                     cs=machine.Pin(5, machine.Pin.OUT),
                     dio0=machine.Pin(2, machine.Pin.IN))
lora.begin()
lora.set_frequency(915000000)  # Adjust band
lora.set_spreading_factor(12)
lora.set_signal_bandwidth(125000)
lora.set_coding_rate(8)
lora.set_tx_power(20)

XOR_KEY = b'\xa1\xb2\xc3\xd4\xe5\xf6\x78\x90\x12\x34\x56\x78\x90\xab\xcd\xef'  # 16B AES-sized

def encrypt_payload(payload, key):
    return bytes(a ^ b for a, b in zip(payload, key * (len(payload) // 16 + 1)))

def pack_lora_packet(temp=25.0, hum=60.0, press=101300, light=5000, dev_id=0x0101, seq=0):
    sensor_pkt = pack_sensor_packet(dev_id, seq, temp, hum, press, light)  # From #1
    nonce = random.getrandbits(32)
    key_id = 0x01
    crypto_hdr = struct.pack('>IB', nonce, key_id)
    enc_payload = encrypt_payload(sensor_pkt, XOR_KEY)
    full_pkt = crypto_hdr + enc_payload
    return full_pkt  # CRC already in sensor_pkt

# TX loop
seq = 0
while True:
    pkt = pack_lora_packet(seq=seq)
    lora.write(full_pkt)  # SX127x send (blocks)
    print("LoRa TX:", [hex(b) for b in pkt[:10]])  # Debug hdr
    seq = (seq + 1) % 256
    time.sleep(30)  # Duty cycle
```

**Teaching Notes**: RX on gateway: `lora.read()`, decrypt XOR, CRC verify, unpack. Discuss AES (`ucryptolib.aes()`), key exchange (Diffie-Hellman header). Test with two ESP32s. Range: 1-10km line-of-sight.

